#!/usr/bin/env python3
"""MASTER: text analysis suite (freq + palindrome + markdown + caesar)."""
import re
from collections import Counter

def freq(t, n=3):
    return Counter(re.findall(r"[a-z]+", t.lower())).most_common(n)
def pals(t):
    return sorted({w for w in re.findall(r"[a-z]+", t.lower()) if w == w[::-1] and len(w) > 1})
def md_h1(md):
    m = re.search(r"^# (.+)$", md, re.M)
    return "<h1>%s</h1>" % m.group(1) if m else ""
def caesar(t, s):
    return "".join(chr((ord(c)-97+s)%26+97) if "a"<=c<="z" else c for c in t)

TEXT = "# Field Notes\n\nAnna found a level radar. Data data data."

if __name__ == "__main__":
    print("top:", freq(TEXT)); print("palindromes:", pals(TEXT))
    print("title:", md_h1(TEXT)); print("cipher:", caesar("abc", 1))
    assert freq(TEXT)[0] == ("data", 3) and pals(TEXT) == ["anna", "level", "radar"]
    assert md_h1(TEXT) == "<h1>Field Notes</h1>" and caesar("abc", 1) == "bcd"
    print("OK: text suite — all four tools verified")

#!/usr/bin/env python3
"""MASTER: crypto mini-suite (passwords + sha256 + caesar + base64)."""
import random, string, hashlib, base64

def gen_pw(n, rng):
    return "".join(rng.choice(string.ascii_letters + string.digits) for _ in range(n))
def sha(t): return hashlib.sha256(t.encode()).hexdigest()
def caesar(t, s):
    f = lambda c: chr((ord(c)-97+s)%26+97) if "a"<=c<="z" else c
    return "".join(f(c) for c in t)
def b64e(t): return base64.b64encode(t.encode()).decode()

if __name__ == "__main__":
    rng = random.Random(3)
    pw = gen_pw(12, rng)
    print("password:", pw, "| sha256:", sha(pw)[:16] + "...")
    assert len(sha(pw)) == 64 and sha("a") != sha("b")
    assert caesar(caesar("hello", 4), -4) == "hello"
    assert base64.b64decode(b64e("x")).decode() == "x"
    print("OK: crypto suite — hash, cipher, encoding all verified")

#!/usr/bin/env python3
"""MASTER: math toolkit (fib + primes + calc + sort + search)."""
import ast, operator

def fib(n):
    a, b = 0, 1
    for _ in range(n): a, b = b, a+b
    return a
def sieve(n):
    sp=[True]*(n+1); sp[0]=sp[1]=False
    for i in range(2,int(n**0.5)+1):
        if sp[i]:
            for j in range(i*i,n+1,i): sp[j]=False
    return [i for i,p in enumerate(sp) if p]
OPS={ast.Add:operator.add,ast.Sub:operator.sub,ast.Mult:operator.mul,ast.Div:operator.truediv}
def calc(e):
    def ev(n):
        if isinstance(n,ast.Expression): return ev(n.body)
        if isinstance(n,ast.Constant): return n.value
        return OPS[type(n.op)](ev(n.left),ev(n.right))
    return ev(ast.parse(e,mode="eval"))
def bsearch(a,t):
    lo,hi=0,len(a)-1
    while lo<=hi:
        m=(lo+hi)//2
        if a[m]==t: return m
        lo,hi=(m+1,hi) if a[m]<t else (lo,m-1)
    return -1

if __name__ == "__main__":
    primes = sieve(200)
    print("primes<200:", len(primes), "| fib(15):", fib(15), "| 6*7:", calc("6*7"))
    s = sorted([5,2,9,1])
    assert fib(15)==610 and calc("6*7")==42 and bsearch(primes,199)==45
    print("OK: math toolkit — 5 tools verified")

#!/usr/bin/env python3
"""MASTER: password toolkit (generate + score + encrypt + encode)."""
import random, string, base64

def gen(n, rng):
    return "".join(rng.choice(string.ascii_letters+string.digits+"!@#") for _ in range(n))
def strength(pw):
    score = len(pw)
    score += 10 if any(c.isdigit() for c in pw) else 0
    score += 10 if any(c.isupper() for c in pw) else 0
    score += 10 if any(c in "!@#" for c in pw) else 0
    return score
def caesar(t,s):
    return "".join(chr((ord(c)-97+s)%26+97) if "a"<=c<="z" else c for c in t)

if __name__ == "__main__":
    rng = random.Random(12)
    pw = gen(14, rng)
    print("password:", pw, "| strength:", strength(pw))
    assert strength(pw) >= 30
    enc = base64.b64encode(caesar(pw,3).encode()).decode()
    back = caesar(base64.b64decode(enc).decode(),-3)
    assert back == pw
    print("OK: password toolkit — generate/score/round-trip verified")

#!/usr/bin/env python3
"""MASTER: unit conversion station (temp + length + weight + expressions)."""
import ast, operator
OPS={ast.Add:operator.add,ast.Sub:operator.sub,ast.Mult:operator.mul,ast.Div:operator.truediv}
def calc(e):
    def ev(n):
        if isinstance(n,ast.Expression): return ev(n.body)
        if isinstance(n,ast.Constant): return n.value
        return OPS[type(n.op)](ev(n.left),ev(n.right))
    return ev(ast.parse(e,mode="eval"))

def convert(value, from_u, to_u):
    table = {"C":("C",lambda x:x),"F":("C",lambda f:(f-32)*5/9),"K":("C",lambda k:k-273.15),
             "m":("m",lambda x:x),"km":("m",lambda x:x*1000),"ft":("m",lambda x:x*0.3048),
             "mi":("m",lambda x:x*1609.344),"kg":("kg",lambda x:x),"lb":("kg",lambda x:x*0.453592)}
    base1, f1 = table[from_u]; base2, f2 = table[to_u]
    assert base1 == base2, "incompatible units"
    # convert via base: invert f2 numerically
    b = f1(value)
    lo, hi = -1e9, 1e9
    for _ in range(100):
        mid=(lo+hi)/2
        if f2(mid) < b: lo=mid
        else: hi=mid
    return (lo+hi)/2

if __name__ == "__main__":
    print("100 C =", convert(100,"C","F"), "F")
    assert abs(convert(100,"C","F")-212)<0.01
    assert abs(convert(calc("5*2"),"km","mi")-6.21371)<1e-4
    assert abs(convert(150,"lb","kg")-68.0388)<1e-3
    print("OK: temp/length/weight conversions + expression input")

#!/usr/bin/env python3
"""MASTER: data validator (json + csv + url + schema)."""
import json, csv, io, re
from urllib.parse import urlparse

def vjson(t):
    try: json.loads(t); return True
    except Exception: return False
def vcsv(t, cols):
    try:
        rows = list(csv.DictReader(io.StringIO(t)))
        return all(set(cols) <= set(r.keys()) for r in rows) and len(rows) > 0
    except Exception: return False
def vurl(u):
    p = urlparse(u); return p.scheme in ("http","https") and bool(p.hostname)
def vschema(rec):
    return bool(re.match(r"^JAH-[A-Z]+-\d+$", rec.get("id",""))) and isinstance(rec.get("title"),str)

if __name__ == "__main__":
    results = {
        "json": vjson('{"a":1}') and not vjson("{bad}"),
        "csv": vcsv("a,b\n1,2\n", ["a","b"]) and not vcsv("a\n1\n", ["a","b"]),
        "url": vurl("https://example.com") and not vurl("notaurl"),
        "schema": vschema({"id":"JAH-REC-000001","title":"T"}) and not vschema({"id":"x"}),
    }
    print(results)
    assert all(results.values())
    print("OK: all four validators pass")

#!/usr/bin/env python3
"""MASTER: flashcard studio (deck builder + timed quiz + mastery)."""
import time

def build_deck(pairs):
    return [{"q": q, "a": a, "box": 1} for q, a in pairs]

def drill(deck, answers):
    t0 = time.perf_counter(); correct = 0
    for card, given in zip(deck, answers):
        if given.strip().lower() == card["a"].lower():
            correct += 1; card["box"] += 1
        else: card["box"] = 1
    return correct, time.perf_counter()-t0

if __name__ == "__main__":
    deck = build_deck([("2+2","4"),("capital of Italy","Rome"),("H2O","water")])
    correct, dt = drill(deck, ["4","rome","fire"])
    print("correct: %d/%d in %.4fs | boxes: %s" % (correct, len(deck), dt, [c["box"] for c in deck]))
    assert correct == 2 and deck[0]["box"] == 2 and deck[2]["box"] == 1
    print("OK: flashcard studio with Leitner boxes works")

#!/usr/bin/env python3
"""MASTER: finance mini (compound interest + loan + split)."""
def compound(principal, rate, years, n=12):
    return principal*(1+rate/n)**(n*years)
def loan_payment(pv, annual_rate, years):
    r = annual_rate/12; m = years*12
    return pv*r/(1-(1+r)**-m) if r else pv/m
def split(total, people):
    c = round(total*100); s, rem = divmod(c, people)
    return [(s+(1 if i<rem else 0))/100 for i in range(people)]

if __name__ == "__main__":
    print("10k at 7%% for 10y: $%.2f" % compound(10000, 0.07, 10))
    assert abs(compound(10000,0.07,10)-20096.61)<1.0
    pmt = loan_payment(20000, 0.05, 5)
    print("20k loan 5%%/5y: $%.2f/mo" % pmt)
    assert abs(pmt-377.42)<0.5
    assert abs(sum(split(100,3))-100)<0.01
    print("OK: finance mini — interest, loan, split verified")

#!/usr/bin/env python3
"""MASTER: file tools (convert + encode + task files)."""
import json, csv, io, base64, os, tempfile

def convert_csv_json(csv_text):
    return json.dumps(list(csv.DictReader(io.StringIO(csv_text))), indent=2)
def encode_file_b64(path):
    return base64.b64encode(open(path,"rb").read()).decode()

if __name__ == "__main__":
    out = convert_csv_json("a,b\n1,2\n")
    assert json.loads(out) == [{"a":"1","b":"2"}]
    path = tempfile.mktemp()
    open(path,"w").write("file-tools demo")
    enc = encode_file_b64(path)
    assert base64.b64decode(enc).decode() == "file-tools demo"
    os.unlink(path)
    print("OK: file tools — CSV/JSON convert + base64 file encode")
